"""Modelo de la tabla `iglesias` (Issue #12 y #4; decisión D8).

Una fila por iglesia del Presbiterio (3ra de Mérida, 4ta, 6ta y Huhí). Las sedes,
horarios y redes sociales se agregan en el segundo PR del Issue #4.
"""

from sqlalchemy import Identity, Integer, String, Text, UniqueConstraint
from sqlalchemy.orm import Mapped, mapped_column

from app.db import Base


class Iglesia(Base):
    """Una iglesia del Presbiterio."""

    __tablename__ = "iglesias"

    # Llave primaria numérica. Identity(always=False) = "GENERATED BY DEFAULT AS IDENTITY":
    # PostgreSQL la numera solo, pero el script de datos de ejemplo (#5) puede fijar ids.
    id: Mapped[int] = mapped_column(Integer, Identity(always=False), primary_key=True)

    # Nombre oficial de la iglesia; no puede repetirse (ver restricción más abajo).
    nombre: Mapped[str] = mapped_column(String(150), nullable=False)

    # Enlace (no archivo) a la foto de fachada (#12). Opcional.
    foto_url: Mapped[str | None] = mapped_column(Text)

    # Nombre del pastor como texto, igual que lo usa el frontend (#12). Opcional.
    pastor: Mapped[str | None] = mapped_column(String(150))

    # Teléfonos opcionales (#12). El del pastor es un dato personal:
    # no debe mostrarse en la página pública.
    telefono_pastor: Mapped[str | None] = mapped_column(String(20))
    telefono_iglesia: Mapped[str | None] = mapped_column(String(20))

    __table_args__ = (
        # No puede haber dos iglesias con el mismo nombre.
        UniqueConstraint("nombre", name="uq_iglesias_nombre"),
    )
